import { Mesh, PlaneGeometry, Object3D } from 'three/webgpu';
import { MeshBasicNodeMaterial, texture, uv } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {{x:number,y:number,z:number}} position
 * @property {{x:number,y:number,z:number}} rotation
 * @property {{x:number,y:number,z:number}} scale
 * @property {{imageUrl:string}} assets
 * @property {any} cinematicPrimitives
 * @property {any} textContent
 * @property {any} behaviorSpec
 */

/**
 * @typedef {Object} NodeContext
 * @property {{load:(url:string)=>any}} textureLoader
 * @property {{emit?:(event:string)=>void}} emit
 * @property {{[key:string]:(obj:any,params:any)=>void}} primitives
 */

/**
 * Create a thumbnail card mesh.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // -----------------------------------------------------------------
  // Geometry – keep the original aspect ratio of the source rect (512:320)
  // -----------------------------------------------------------------
  const aspect = 512 / 320; // width / height
  const width = 1 * aspect; // base height 1 unit
  const height = 1;
  const geometry = new PlaneGeometry(width, height);

  // -----------------------------------------------------------------
  // Texture – synchronous load from the provided URL
  // -----------------------------------------------------------------
  const tex = ctx.textureLoader.load(config.assets?.imageUrl ?? '');

  // -----------------------------------------------------------------
  // Material – simple unlit node material
  // -----------------------------------------------------------------
  const material = new MeshBasicNodeMaterial();
  material.colorNode = texture(tex);
  material.alphaNode = texture(tex, uv()).a; // preserve texture alpha if any
  material.transparent = true;

  // -----------------------------------------------------------------
  // Mesh assembly
  // -----------------------------------------------------------------
  const mesh = new Mesh(geometry, material);
  mesh.position.set(
    config.position?.x ?? 0,
    config.position?.y ?? 0,
    config.position?.z ?? 0
  );
  mesh.rotation.set(
    config.rotation?.x ?? 0,
    config.rotation?.y ?? 0,
    config.rotation?.z ?? 0
  );
  mesh.scale.set(
    config.scale?.x ?? 1,
    config.scale?.y ?? 1,
    config.scale?.z ?? 1
  );

  // -----------------------------------------------------------------
  // Interaction handling (hover lift, click emit)
  // -----------------------------------------------------------------
  const originalY = mesh.position.y;
  const hoverRise = 0.15; // scene units

  const timelineRefs = new Set();

  const handleHoverEnter = () => {
    const t = gsap.to(mesh.position, {
      y: originalY + hoverRise,
      duration: 0.15,
      ease: 'power3.out',
    });
    timelineRefs.add(t);
  };

  const handleHoverLeave = () => {
    const t = gsap.to(mesh.position, {
      y: originalY,
      duration: 0.15,
      ease: 'power3.out',
    });
    timelineRefs.add(t);
  };

  const handleClick = () => {
    if (ctx.emit) ctx.emit('hub-journal.select');
  };

  // Attach handlers to userData – the hosting system will bind them to pointer events
  mesh.userData.handlers = {
    pointerenter: handleHoverEnter,
    pointerleave: handleHoverLeave,
    click: handleClick,
  };

  // -----------------------------------------------------------------
  // Cleanup routine
  // -----------------------------------------------------------------
  mesh.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();
    if (tex && tex.dispose) tex.dispose();

    // Kill any running GSAP tweens
    timelineRefs.forEach((t) => {
      t.kill();
    });
    timelineRefs.clear();
    gsap.killTweensOf(mesh.position);
  };

  // -----------------------------------------------------------------
  // Return the mesh (no additional group required)
  // -----------------------------------------------------------------
  return mesh;
}
